def glance(what,time,get,now=WAIT):
    rows=[('what','What it is',what),('time','Time',time),('inv','Investment',INV),('get','What you get',get),('now','Why now',now)]
    return '<section class="glance"><div class="lab">At a glance</div><dl>'+''.join(f'<div class="row">{IC[k]}<div><dt>{t}</dt><dd>{d}</dd></div></div>' for k,t,d in rows)+'</dl></section>'
def ul(items): return '<ul>'+''.join(f'<li>{x}</li>' for x in items)+'</ul>'
EVERY='<section class="every two"><div class="lab">In every program</div><span>Your résumé</span><span>Hands-on AI automation and coaching for your day to day</span></section>'
FOOT=f'''<div class="foot"><div><h3>Angela Gallitano · The Gallitano Studio</h3><p>One of three leaders of LinkedIn’s global Rock Your Profile program. Then Gartner, working with CHROs, CIOs and their executive teams. Today, Salesforce Enterprise AI. I build with agentic AI daily, and I teach leaders to do the same. 350+ rooms since 2020. 125+ executives one to one. Every engagement is strictly guarded.</p></div>
<div class="cta"><div><b>Book a 20-minute conversation</b><a>thegallitanostudio.com/book</a><small>Referred? Note your introduction when scheduling.</small><small>angela@thegallitanostudio.com</small></div><img src="file://{R}/qr-book.svg"></div></div>'''
def page(title,tag,hero,body):
    co=' co' if ('companies' in tag or title in ('Known For Executive','Known For First Look')) else ''
    return f'<!doctype html><html lang="en"><meta charset="utf-8"><title>{title}: fact sheet</title><link rel="stylesheet" href="base.css">\n<div class="page{co}">\n<div class="top">{WM}<span class="tag">{tag}</span></div>\n{hero}\n{body}\n{FOOT}\n</div></html>'
def hero(lab,h1,prog='',sub=''):
    return f'<section class="hero"><div class="lab">{lab}</div><h1>{h1}</h1>'+(f'<div class="prog">{prog}</div>' if prog else '')+(f'<p class="sub">{sub}</p>' if sub else '')+'</section>'
def steps(items,cls=''):
    return f'<div class="steps {cls}">'+''.join(f'<div><i>{n+1}</i><b>{a}</b>{b}</div>' for n,(a,b) in enumerate(items))+'</div>'
def runs3(items): return runs(items,'three')
def runs(items,cls=''): return f'<section class="runs"><div class="lab">How it runs</div><h2>Your LinkedIn, your bio and your site are collateral. The work is narrative architecture and category ownership.</h2>{steps(items,cls)}</section>'
def cards(a,b): return f'<section class="get"><div class="card t"><div class="lab">The strategy</div>{ul(a)}</div><div class="card o"><div class="lab">Where it shows up</div>{ul(b)}</div></section>'
def leave(ps,note): return '<section class="leave"><div class="lab">What you leave with</div>'+''.join(f'<p>{p}</p>' for p in ps)+f'<p class="pause">{note}</p></section>'
